module logic;
use model {Hit,Search};
use util {reverse};
fn equal_at(text:Text,needle:Text,start:I64)->Bool {
 let count=Text::length(needle);
 let final=fold(i in count,state:Bool=true) {
  state && Text::at(text,start+i)==Text::at(needle,i)
 };final
}
fn run(text:Text,needle:Text,start:I64)->Search<Hit> {
 let text_len=Text::length(text);
 let needle_len=Text::length(needle);
 if start<0 || start>text_len {
  Invalid(start)
 } else {
  if needle_len==0 {
   Found(Hit {index:start,prefix:Text::slice(text,0,start),suffix:Text::slice(text,start,text_len-start),match_bytes:0})
  } else {
   let answer=fold(i in text_len,state:Search<Hit>=Missing) {
    match state {
     Found(hit)=>Found(hit),
     Missing=>if i>=start && needle_len<=text_len-i && equal_at(text,needle,i) {
      let end=i+needle_len;
      Found(Hit {index:i,prefix:Text::slice(text,0,i),suffix:Text::slice(text,end,text_len-end),match_bytes:Bytes::length(Text::bytes(needle))})
     } else {Missing},
     Invalid(bad)=>Invalid(bad)
    }
   };answer
  }
 }
}

